-- Catalog-only comparison: no application records, credentials or tokens.
begin read only;
set local search_path = public, pg_catalog;
select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.table_name,'name',c.column_name,'position',c.ordinal_position,'type',c.udt_name,'nullable',c.is_nullable,'default',c.column_default,'length',c.character_maximum_length,'precision',c.numeric_precision,'scale',c.numeric_scale)) from information_schema.columns c where c.table_schema='public'),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated)) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and c.contype<>'n'),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef)) from pg_indexes where schemaname='public'),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',roles,'cmd',cmd,'using',qual,'check',with_check)) from pg_policies where schemaname in ('public','storage')),
 'triggers',(select jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname='public' or t.tgname='on_auth_user_created_profile')),
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'body',regexp_replace(p.prosrc,'\s+','','g'),'language',l.lanname,'definer',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'strict',p.proisstrict,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'auth_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname<>'rls_auto_enable'),
 'table_privileges',(select jsonb_agg(jsonb_build_object('table',c.relname,'role',r.name,'select',has_table_privilege(r.name,c.oid,'SELECT'),'insert',has_table_privilege(r.name,c.oid,'INSERT'),'update',has_table_privilege(r.name,c.oid,'UPDATE'),'delete',has_table_privilege(r.name,c.oid,'DELETE'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join (values('anon'),('authenticated')) r(name) where n.nspname='public' and c.relkind='r'),
 'column_privileges',(select jsonb_agg(jsonb_build_object('table',c.table_name,'column',c.column_name,'role',r.name,'select',has_column_privilege(r.name,format('%I.%I',c.table_schema,c.table_name),c.column_name,'SELECT'),'insert',has_column_privilege(r.name,format('%I.%I',c.table_schema,c.table_name),c.column_name,'INSERT'),'update',has_column_privilege(r.name,format('%I.%I',c.table_schema,c.table_name),c.column_name,'UPDATE'))) from information_schema.columns c cross join (values('anon'),('authenticated')) r(name) where c.table_schema='public'),
 'avatar_bucket',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'size',file_size_limit,'mimes',allowed_mime_types)) from storage.buckets where id='profile-avatars')
) as snapshot;
rollback;
